import{_ as a,o as e,c as i,a0 as o}from"./chunks/framework.L_oL6aia.js";const u=JSON.parse('{"title":"OpenWrt 路由器端配置 VPN 教程","description":"","frontmatter":{},"headers":[],"relativePath":"guide/openwrt.md","filePath":"guide/openwrt.md"}'),r={name:"guide/openwrt.md"};function t(n,l,s,p,h,d){return e(),i("div",null,[...l[0]||(l[0]=[o('<h1 id="openwrt-路由器端配置-vpn-教程" tabindex="-1">OpenWrt 路由器端配置 VPN 教程 <a class="header-anchor" href="#openwrt-路由器端配置-vpn-教程" aria-label="Permalink to &quot;OpenWrt 路由器端配置 VPN 教程&quot;">​</a></h1><p>通过在路由器端配置 VPN，可以让家庭或办公网络内的所有设备共享同一条 VPN 通道，无需在每台设备上单独安装客户端。本文以常见的 <strong>OpenWrt 路由器</strong>为例进行说明。</p><h2 id="一、准备工作" tabindex="-1">一、准备工作 <a class="header-anchor" href="#一、准备工作" aria-label="Permalink to &quot;一、准备工作&quot;">​</a></h2><ol><li>一台支持刷 OpenWrt 的路由器（或自带 VPN 功能的品牌路由器）</li><li>已购买并获取到 VPN 服务的配置信息（如节点地址、用户名、密码、密钥或配置文件）</li><li>一台电脑，用于登录路由器管理后台</li></ol><h2 id="二、登录路由器后台" tabindex="-1">二、登录路由器后台 <a class="header-anchor" href="#二、登录路由器后台" aria-label="Permalink to &quot;二、登录路由器后台&quot;">​</a></h2><ol><li>将路由器连接电源和网线，电脑通过有线或无线方式接入路由器</li><li>在浏览器输入 <code>192.168.1.1</code> 或实际管理地址</li><li>输入管理员用户名和密码，进入后台管理界面</li></ol><h2 id="三、安装-vpn-插件-openwrt" tabindex="-1">三、安装 VPN 插件（OpenWrt） <a class="header-anchor" href="#三、安装-vpn-插件-openwrt" aria-label="Permalink to &quot;三、安装 VPN 插件（OpenWrt）&quot;">​</a></h2><p>如果使用的是 OpenWrt 系统，可以选择以下常见插件：</p><ul><li><strong>OpenVPN 客户端</strong>：适用于 <code>.ovpn</code> 配置文件</li><li><strong>Passwall / SSR Plus / OpenClash</strong>：适用于 V2Ray、Trojan、Clash 等协议</li></ul><p>安装方式：</p><ol><li>进入「系统 &gt; 软件包」</li><li>点击更新软件列表</li><li>搜索并安装所需插件（如 <code>openvpn-openssl</code>、<code>luci-app-passwall</code>、<code>luci-app-openclash</code> 等）</li></ol><h2 id="四、导入-vpn-配置" tabindex="-1">四、导入 VPN 配置 <a class="header-anchor" href="#四、导入-vpn-配置" aria-label="Permalink to &quot;四、导入 VPN 配置&quot;">​</a></h2><h3 id="方式一-openvpn" tabindex="-1">方式一：OpenVPN <a class="header-anchor" href="#方式一-openvpn" aria-label="Permalink to &quot;方式一：OpenVPN&quot;">​</a></h3><ol><li>打开「服务 &gt; OpenVPN」</li><li>点击「添加」并上传 <code>.ovpn</code> 配置文件</li><li>输入用户名和密码（如服务商要求）</li><li>保存并启用</li></ol><h3 id="方式二-passwall-ssr-plus" tabindex="-1">方式二：Passwall / SSR Plus <a class="header-anchor" href="#方式二-passwall-ssr-plus" aria-label="Permalink to &quot;方式二：Passwall / SSR Plus&quot;">​</a></h3><ol><li>打开插件界面</li><li>添加新节点，填写服务器地址、端口、协议类型、密码或密钥</li><li>保存并应用配置</li></ol><h3 id="方式三-openclash" tabindex="-1">方式三：OpenClash <a class="header-anchor" href="#方式三-openclash" aria-label="Permalink to &quot;方式三：OpenClash&quot;">​</a></h3><ol><li>上传 Clash 订阅链接或配置文件</li><li>选择需要启用的节点</li><li>点击「启动」</li></ol><h2 id="五、防火墙与分流设置-可选" tabindex="-1">五、防火墙与分流设置（可选） <a class="header-anchor" href="#五、防火墙与分流设置-可选" aria-label="Permalink to &quot;五、防火墙与分流设置（可选）&quot;">​</a></h2><ol><li>确保防火墙允许 VPN 流量转发</li><li>根据需要选择「全局代理」或「仅代理国外流量」</li><li>在路由器中设置 DNS，避免 DNS 污染</li></ol><h2 id="六、验证是否生效" tabindex="-1">六、验证是否生效 <a class="header-anchor" href="#六、验证是否生效" aria-label="Permalink to &quot;六、验证是否生效&quot;">​</a></h2><ol><li>连接路由器的 Wi-Fi 或网线</li><li>在浏览器访问 <a href="https://ip.sb" target="_blank" rel="noreferrer">https://ip.sb</a></li><li>检查 IP 地址是否与 VPN 节点一致</li><li>如果一致，说明 VPN 已在路由器端运行成功</li></ol><h2 id="七、注意事项" tabindex="-1">七、注意事项 <a class="header-anchor" href="#七、注意事项" aria-label="Permalink to &quot;七、注意事项&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><ul><li>不同路由器型号支持的插件不同，建议优先选择 OpenWrt</li><li>部分运营商可能屏蔽常见 VPN 端口，可尝试更换协议或端口</li><li>若出现掉线或不稳定情况，可尝试更换 DNS 或节点</li></ul></div><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>通过在路由器端配置 VPN，全网设备无需单独设置，即可享受统一的加密访问和外网体验。推荐有一定动手能力的用户尝试 OpenWrt 或选择具备 VPN 功能的路由器。</p>',26)])])}const P=a(r,[["render",t]]);export{u as __pageData,P as default};
